<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(403);exit;}require __DIR__.'/model.php';$count=0;function check($v,$msg){if(!$v)throw new RuntimeException($msg);}function test($name,$f){global $count;$f();$count++;echo "PASS $name\n";}function near($a,$b,$t=1e-8){check(abs($a-$b)<=$t*max(1,abs($b)),"$a != $b");}
foreach(records() as $id=>$r)test('source and relation '.$id,function()use($id,$r){check(isset(corpus()['statuses'][$r['status']]),'status');check(min($r['pages'])>=1&&max($r['pages'])<=129,'pages');check(is_file(__DIR__.'/../ledger/'.$id.'/index.php'),'route');foreach($r['gates'] as $g)check(in_array($g,array_column(corpus()['gates'],'id'),true),'gate');if($r['workbench'])check(isset(specs()[$r['workbench']]),'workbench');});
foreach([0,1,2,3.999999,4,4.000001,8,16] as $ratio)test('escape conservation '.$ratio,function()use($ratio){$r=calc('escape',['ratio'=>$ratio,'duration'=>40]);$prev=-1;$prevTotal=-1;foreach($r['rows'] as $row){near($row[1]+$row[2]+$row[3],1);check(min(array_slice($row,1))>=-1e-12,'negative probability');check($row[3]>=$prev-1e-12,'escape monotonic');if($ratio>=4)check($row[4]>=$prevTotal-1e-12,'total monotonic');$prev=$row[3];$prevTotal=$row[4];}});
test('zero escape exact null',function(){foreach(calc('escape',['ratio'=>0])['rows'] as $row)near($row[3],0);});test('underdamped derivative reversal',function(){check(calc('escape',['ratio'=>2])['metrics'][3]['value']<0,'back conversion');});test('critical analytic solution',function(){$r=calc('escape',['ratio'=>4,'duration'=>1]);$row=end($r['rows']);near($row[1],4*exp(-2));near($row[2],exp(-2));});test('wall review reference',function(){$m=calc('wall')['metrics'];near($m[1]['value'],19.89975,1e-6);near($m[2]['value'],3.28345,2e-6);check($m[3]['value']==='No feasible interval','interval');});test('wall tiny gap bound',function(){$v=calc('wall',['loggap'=>-16,'ceiling'=>1.1])['metrics'][0]['value'];check(abs($v/2.400396792595916e-16-1)<1e-9,'bound');});test('anchor review reference',function(){$m=calc('anchors')['metrics'];near($m[0]['value'],4.53,.001);near($m[1]['value'],3.39,.001);});test('anchor zero shift',function(){$m=calc('anchors',['percent'=>0])['metrics'];near($m[0]['value'],0);near($m[1]['value'],0);});foreach(specs() as $id=>$s){test('finite rows '.$id,function()use($id){$r=calc($id);foreach($r['rows'] as $row){check(count($row)===count($r['series'])+1,'shape');foreach($row as $v)check(is_finite($v),'finite');}});test('reject malformed parameters '.$id,function()use($id,$s){foreach([['unknown'=>1],[array_key_first($s['params'])=>[]],[array_key_first($s['params'])=>null],[array_key_first($s['params'])=>99999]] as $p){try{calc($id,$p);throw new RuntimeException('accepted bad input');}catch(InvalidArgumentException $e){}}});}echo "$count passed, 0 failed\n";
